using UnityEngine;using UnityEditor;using System.IO;using System.Linq;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class BridgeStripAudit{static BridgeStripAudit(){EditorApplication.update+=Run;}static void Run(){if(EditorApplication.isCompiling||!File.Exists("BridgeStripAudit.request"))return;File.Delete("BridgeStripAudit.request");var sc=SceneManager.GetActiveScene();File.WriteAllLines("FinalEnvironmentRoadReview/BridgeStripAudit.txt",sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.name.ToLower().Contains("bridge")||r.transform.GetComponentsInParent<Transform>().Any(t=>t.name.Contains("Bridge Super")||t.name.StartsWith("Bridge 0"))).Select(r=>r.name+" | "+r.transform.parent.name+" | "+r.bounds+" | "+string.Join(",",r.sharedMaterials.Select(m=>m?AssetDatabase.GetAssetPath(m):"null"))+" | "+AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh)));}}
